9	/// 折线 / 面积图，虚线标均值。
10	///
11	/// 画之前先过一遍 [RideSeriesSmooth.prepare]：GNSS 抖出来的孤立尖峰在这里被
12	/// 摘掉，线本身再用单调三次曲线连起来 —— 直角折线在 130 px 高的卡片里看着
13	/// 像振动，不像趋势。
14	class RideSeriesChart extends StatefulWidget {
15	  const RideSeriesChart({
16	    super.key,
17	    required this.values,
18	    required this.color,
19	    this.fill = false,
20	    this.avg,
21	    this.smooth = true,
22	    this.animate = true,
23	    this.maxPoints = 160,
24	  });
25	
26	  final List<double> values;
27	  final Color color;
28	  final bool fill;
29	  final double? avg;
30	
31	  /// 是否做去尖峰 + 平滑。原始序列（如速度条）不要走这里。
32	  final bool smooth;
33	
34	  /// 进场时从左往右画出来。卡片在抽屉展开时才首次 build，正好播一次。
35	  final bool animate;
36	
37	  /// 平滑后保留的点数上限。
38	  final int maxPoints;
39	
40	  @override
41	  State<RideSeriesChart> createState() => _RideSeriesChartState();
42	
43	  /// 按位置取样降采样（保留尖峰）。平滑序列不要用它。
44	  static List<double> downsample(List<double> src, int maxN) {
45	    if (src.length <= maxN) return src;
46	    final out = <double>[];
47	    for (var i = 0; i < maxN; i++) {
48	      final idx = (i * (src.length - 1) / (maxN - 1)).round();
49	      out.add(src[idx]);
50	    }
51	    return out;
52	  }
53	}
