55	class _RideSeriesChartState extends State<RideSeriesChart> {
56	  List<double> _src = const [];
57	  List<double> _prepared = const [];
58	  bool _smooth = true;
59	  int _maxPoints = 160;
60	  bool _ready = false;
61	
62	  @override
63	  void initState() {
64	    super.initState();
65	    _sync();
66	  }
67	
68	  @override
69	  void didUpdateWidget(covariant RideSeriesChart old) {
70	    super.didUpdateWidget(old);
71	    _sync();
72	  }
73	
74	  /// 抽屉拖动时整张卡片会逐帧重建，而平滑是 O(n·w) 的整条序列计算 ——
75	  /// 每帧重算会把拖拽帧预算吃掉。这里按**内容**判断是否需要重算：
76	  /// 卡片每次 build 都会新建一个 values 列表，比身份（identical）永远不等。
77	  /// 一次线性比较的成本可以忽略，换来的是平滑只在数据变化时跑一次。
78	  void _sync() {
79	    final v = widget.values;
80	    if (_ready &&
81	        _smooth == widget.smooth &&
82	        _maxPoints == widget.maxPoints &&
83	        listEquals(v, _src)) {
84	      return;
85	    }
86	    _smooth = widget.smooth;
87	    _maxPoints = widget.maxPoints;
88	    _src = List<double>.of(v);
89	    _prepared = widget.smooth
90	        ? RideSeriesSmooth.prepare(v, maxN: widget.maxPoints)
91	        : RideSeriesChart.downsample(v, 180);
92	    _ready = true;
93	  }
94	
95	  @override
96	  Widget build(BuildContext context) {
97	    Widget paint(double reveal) => CustomPaint(
98	      painter: _SeriesPainter(
99	        values: _prepared,
100	        color: widget.color,
101	        fill: widget.fill,
102	        avg: widget.avg,
103	        reveal: reveal,
104	      ),
105	      child: const SizedBox.expand(),
106	    );
107	    if (!widget.animate) return paint(1);
108	    return TweenAnimationBuilder<double>(
109	      tween: Tween<double>(begin: 0, end: 1),
110	      duration: const Duration(milliseconds: 760),
111	      curve: Curves.easeOutCubic,
112	      builder: (context, t, _) => paint(t),
113	    );
114	  }
115	}
