117	class _SeriesPainter extends CustomPainter {
118	  _SeriesPainter({
119	    required this.values,
120	    required this.color,
121	    required this.fill,
122	    required this.avg,
123	    this.reveal = 1,
124	  });
125	
126	  final List<double> values;
127	  final Color color;
128	  final bool fill;
129	  final double? avg;
130	
131	  /// 0..1：只画到这一段宽度（进场揭示）。1 = 整条。
132	  final double reveal;
133	
134	  @override
135	  void paint(Canvas canvas, Size size) {
136	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
137	    const pad = EdgeInsets.fromLTRB(4, 10, 4, 6);
138	    final w = size.width - pad.left - pad.right;
139	    final h = size.height - pad.top - pad.bottom;
140	    if (w <= 0 || h <= 0) return;
141	
142	    var minV = values.reduce(math.min);
143	    var maxV = values.reduce(math.max);
144	    if (avg != null) {
145	      minV = math.min(minV, avg!);
146	      maxV = math.max(maxV, avg!);
147	    }
148	    if (maxV - minV < 0.2) {
149	      minV -= 1;
150	      maxV += 1;
151	    }
152	    final span = maxV - minV;
153	
154	    Offset pt(int i, double v) {
155	      final x = pad.left +
156	          (values.length == 1 ? w / 2 : w * i / (values.length - 1));
157	      final y = pad.top + h * (1 - (v - minV) / span);
158	      return Offset(x, y);
159	    }
160	
161	    final pts = [for (var i = 0; i < values.length; i++) pt(i, values[i])];
162	    final line = monotonePath(pts);
163	
164	    final r = reveal.clamp(0.0, 1.0);
165	    final revealed = r < 1;
166	    if (revealed) {
167	      canvas.save();
168	      canvas.clipRect(Rect.fromLTWH(0, 0, size.width * r, size.height));
169	    }
170	
171	    // 只有一个采样点时路径退化成 moveTo，描边和填充都画不出东西 ——
172	    // 画个点，别让「整趟只有一个 0 踏频采样」的卡片变成空白。
173	    if (pts.length == 1) {
174	      canvas.drawCircle(pts.first, 2.8, Paint()..color = color);
175	    }
176	
177	    if (fill) {
178	      final area = Path.from(line)
179	        ..lineTo(pts.last.dx, pad.top + h)
180	        ..lineTo(pts.first.dx, pad.top + h)
181	        ..close();
182	      canvas.drawPath(
183	        area,
184	        Paint()
185	          ..shader = LinearGradient(
186	            begin: Alignment.topCenter,
187	            end: Alignment.bottomCenter,
188	            colors: [
189	              color.withValues(alpha: 0.42),
190	              color.withValues(alpha: 0.02),
191	            ],
192	          ).createShader(Offset.zero & size),
193	      );
194	    }
195	
196	    canvas.drawPath(
197	      line,
198	      Paint()
199	        ..color = color
200	        ..style = PaintingStyle.stroke
201	        ..strokeWidth = 2.2
202	        ..strokeJoin = StrokeJoin.round
203	        ..strokeCap = StrokeCap.round,
204	    );
205	
206	    final a = avg;
207	    if (a != null) {
208	      final y = pt(0, a).dy;
209	      _dash(
210	        canvas,
211	        Offset(pad.left, y),
212	        Offset(pad.left + w, y),
213	        Paint()
214	          ..color = color.withValues(alpha: 0.7)
215	          ..strokeWidth = 1.2,
216	      );
217	    }
218	
219	    if (revealed) canvas.restore();
220	  }
221	
222	  /// 单调三次曲线（Fritsch–Carlson）：相邻两点之间用 Bézier 连接，切线在
223	  /// 局部极值处置 0，所以平滑之后**不会在极值附近过冲** —— 普通 Catmull-Rom
224	  /// 会把尖峰画成一个超出数据范围的鼓包，读数就成了假的。
225	  static Path monotonePath(List<Offset> p) {
226	    final path = Path();
227	    if (p.isEmpty) return path;
228	    path.moveTo(p.first.dx, p.first.dy);
229	    final n = p.length;
230	    if (n == 1) return path;
231	    if (n == 2) {
232	      path.lineTo(p[1].dx, p[1].dy);
233	      return path;
234	    }
235	    final d = List<double>.filled(n - 1, 0);
236	    for (var i = 0; i < n - 1; i++) {
237	      final dx = p[i + 1].dx - p[i].dx;
238	      d[i] = dx.abs() < 1e-6 ? 0 : (p[i + 1].dy - p[i].dy) / dx;
239	    }
240	    final m = List<double>.filled(n, 0);
241	    for (var i = 1; i < n - 1; i++) {
242	      // 极值点切线取 0：曲线在峰顶是平的，不会冲过头。
243	      m[i] = d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2;
244	    }
245	    m[0] = d.first;
246	    m[n - 1] = d.last;
247	    for (var i = 0; i < n - 1; i++) {
248	      if (d[i] == 0) {
249	        m[i] = 0;
250	        m[i + 1] = 0;
251	        continue;
252	      }
253	      final a = m[i] / d[i];
254	      final b = m[i + 1] / d[i];
255	      final s = a * a + b * b;
256	      if (s > 9) {
257	        final t = 3 / math.sqrt(s);
258	        m[i] = t * a * d[i];
259	        m[i + 1] = t * b * d[i];
260	      }
261	    }
262	    for (var i = 0; i < n - 1; i++) {
263	      final dx = p[i + 1].dx - p[i].dx;
264	      path.cubicTo(
265	        p[i].dx + dx / 3,
266	        p[i].dy + m[i] * dx / 3,
267	        p[i + 1].dx - dx / 3,
268	        p[i + 1].dy - m[i + 1] * dx / 3,
269	        p[i + 1].dx,
270	        p[i + 1].dy,
271	      );
272	    }
273	    return path;
274	  }
