276	  static void _dash(Canvas canvas, Offset a, Offset b, Paint paint) {
277	    const dash = 5.0;
278	    const gap = 4.0;
279	    final len = (b - a).distance;
280	    if (len < 1) return;
281	    final dir = (b - a) / len;
282	    var t = 0.0;
283	    while (t < len) {
284	      final end = math.min(t + dash, len);
285	      canvas.drawLine(a + dir * t, a + dir * end, paint);
286	      t += dash + gap;
287	    }
288	  }
