352	class _BarPainter extends CustomPainter {
353	  _BarPainter({
354	    required this.values,
355	    required this.labels,
356	    required this.color,
357	    required this.avg,
358	    required this.avgText,
359	    required this.highlight,
360	  });
361	
362	  final List<double> values;
363	  final List<String> labels;
364	  final Color color;
365	  final double? avg;
366	  final String? avgText;
367	  final int highlight;
368	
369	  static const _emptyBar = Color(0xFF3A3A3C);
370	  static const _labelColor = Color(0xFF8E8E93);
371	
372	  @override
373	  void paint(Canvas canvas, Size size) {
374	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
375	    final w = size.width;
376	    // 有标签才留那一行；迷你图（labels 全空）就贴边画，别浪费高度。
377	    final hasLabel = labels.any((l) => l.isNotEmpty);
378	    final padTop = hasLabel ? 10.0 : 3.0;
379	    final padBottom = hasLabel ? 17.0 : 3.0;
380	    final h = size.height - padTop - padBottom;
381	    if (h <= 0) return;
382	
383	    final maxV = values.fold<double>(0, math.max);
384	    final scaleMax = math.max(maxV, avg ?? 0) * 1.12;
385	    final slot = w / values.length;
386	    final barW = math.min(slot * 0.62, 18.0);
387	
388	    for (var i = 0; i < values.length; i++) {
389	      final v = values[i];
390	      final cx = slot * (i + 0.5);
391	      final frac = scaleMax <= 0 ? 0.0 : (v / scaleMax).clamp(0.0, 1.0);
392	      // 0 也留 2 px 灰底：能看出「这一天存在、只是没骑」。
393	      final barH = frac <= 0 ? 2.0 : math.max(2.0, h * frac);
394	      final isHi = i == highlight;
395	
396	      canvas.drawRRect(
397	        RRect.fromRectAndRadius(
398	          Rect.fromLTWH(cx - barW / 2, padTop + h - barH, barW, barH),
399	          Radius.circular(math.min(barW / 2, 3)),
400	        ),
401	        Paint()
402	          ..color = v <= 0
403	              ? _emptyBar
404	              : (isHi ? color : color.withValues(alpha: 0.55)),
405	      );
406	
407	      final label = i < labels.length ? labels[i] : '';
408	      if (label.isEmpty) continue;
409	      final tp = TextPainter(
410	        text: TextSpan(
411	          text: label,
412	          style: TextStyle(
413	            color: isHi ? Colors.white : _labelColor,
414	            fontSize: 10,
415	            fontWeight: isHi ? FontWeight.w700 : FontWeight.w400,
416	          ),
417	        ),
418	        textDirection: TextDirection.ltr,
419	      )..layout();
420	      tp.paint(canvas, Offset(cx - tp.width / 2, size.height - padBottom + 4));
421	    }
422	
423	    final a = avg;
424	    if (a != null && a > 0) {
425	      final y = padTop + h * (1 - (a / scaleMax).clamp(0.0, 1.0));
426	      final paint = Paint()
427	        ..color = color.withValues(alpha: 0.85)
428	        ..strokeWidth = 1.4;
429	      _SeriesPainter._dash(canvas, Offset(0, y), Offset(w, y), paint);
430	
431	      // 数值标签贴在线右端上方：只有一条线看不出它落在哪一档。
432	      final text = avgText;
433	      if (text != null && text.isNotEmpty) {
434	        final tp = TextPainter(
435	          text: TextSpan(
436	            text: text,
437	            style: TextStyle(
438	              color: color,
439	              fontSize: 9,
440	              fontWeight: FontWeight.w700,
441	            ),
442	          ),
443	          textDirection: TextDirection.ltr,
444	        )..layout();
445	        tp.paint(canvas, Offset(w - tp.width, y - tp.height - 2));
446	      }
447	    }
448	  }
449	
450	  @override
451	  bool shouldRepaint(covariant _BarPainter old) =>
452	      old.values != values ||
453	      old.labels != labels ||
454	      old.color != color ||
455	      old.avg != avg ||
456	      old.avgText != avgText ||
457	      old.highlight != highlight;
458	}
