486	class _PacePainter extends CustomPainter {
487	  _PacePainter({required this.speeds, this.range});
488	
489	  final List<double> speeds;
490	  final ({double lo, double hi})? range;
491	
492	  @override
493	  void paint(Canvas canvas, Size size) {
494	    final r = RRect.fromRectAndRadius(
495	      Offset.zero & size,
496	      const Radius.circular(5),
497	    );
498	    canvas.save();
499	    canvas.clipRRect(r);
500	    if (speeds.length < 2) {
501	      canvas.drawRRect(
502	        r,
503	        Paint()
504	          ..shader = const LinearGradient(
505	            colors: [
506	              RideTrackStyle.bandSlow,
507	              RideTrackStyle.bandMid,
508	              RideTrackStyle.bandFast,
509	            ],
510	          ).createShader(Offset.zero & size),
511	      );
512	    } else {
513	      final minV = range?.lo ?? speeds.reduce(math.min);
514	      final maxV = range?.hi ?? speeds.reduce(math.max);
515	      final w = size.width / speeds.length;
516	      for (var i = 0; i < speeds.length; i++) {
517	        // 与轨迹线共用同一个映射（[RideTrackStyle.speedBandColor]），颜色才对得上。
518	        canvas.drawRect(
519	          Rect.fromLTWH(i * w, 0, w + 0.6, size.height),
520	          Paint()..color = RideTrackStyle.speedBandColor(speeds[i], minV, maxV),
521	        );
522	      }
523	    }
524	    canvas.restore();
525	  }
526	
527	  @override
528	  bool shouldRepaint(covariant _PacePainter old) =>
529	      old.speeds != speeds || old.range != range;
530	}
