36	class _RideDetailPageState extends State<RideDetailPage>
37	    with TickerProviderStateMixin {
38	  final _shotKey = GlobalKey();
39	  final _map = MapController();
40	  final _shareMap = MapController();
41	  RideRecord? _rec;
42	  GpxSummary? _sum;
43	  List<LatLng> _pts = const [];
44	  List<LatLng> _disp = const [];
45	  bool _sharing = false;
46	  late final AnimationController _sheet;
47	
48	  /// 轨迹回放：0..1 = 走完整条。进场自动播一次，最长 [_playMaxSec] 秒。
49	  late final AnimationController _play;
50	
51	  /// 回放是否在跑。游标静止时底栏回落到汇总口径，靠它切换。
52	  bool _playing = false;
53	
54	  /// 回放中的瞬时读数。用 ValueNotifier 单独推给底栏那四格 ——
55	  /// 整页 60 fps 重建会把地图、抽屉和毛玻璃一起带上。
56	  final ValueNotifier<RideGlanceLive?> _liveHud = ValueNotifier(null);
57	  int _hudTick = 0;
58	
59	  /// 回放压缩上限：再长的骑行也在 10 秒内播完。
60	  static const _playMaxSec = 10.0;
61	
62	  /// 每个点的累计骑行秒数（由「距离 / 速度」还原的真实节奏）。
63	  List<double> _rideT = const [];
64	  double _rideTotal = 0;
65	
66	  /// 整条轨迹的色标。加载时算一次，回放只做切片（逐帧重算平滑会掉帧）。
67	  List<Color> _stops = const [];
68	
69	  /// 公里牌位置。同样是整条轨迹量级的计算，加载时算一次。
70	  List<({LatLng ll, int km, double at})> _kmMarks = const [];
71	
72	  /// 初始相机按 padding 缓存：`CameraFit.bounds().fit()` 要投影整条轨迹，
73	  /// 抽屉每一帧拖动 / 回放每一帧重建都会重新调它，而它只在首帧有用。
74	  final Map<EdgeInsets, ({LatLng center, double zoom})> _camCache = {};
