76	  @override
77	  void initState() {
78	    super.initState();
79	    final name = Get.arguments as String?;
80	    if (name != null) {
81	      // 先看骑行记录；没有就去 GPX 库找 —— 那边（导入的、地图上画好的）文件
82	      // 不在这张表里，以前点开是空白页。
83	      _rec = RideRecordStore().find(name) ?? _fromLibrary(name);
84	    }
85	    _loadPts();
86	    _sheet = AnimationController(
87	      vsync: this,
88	      duration: const Duration(milliseconds: 280),
89	    )..addStatusListener((status) {
90	        if (status == AnimationStatus.completed ||
91	            status == AnimationStatus.dismissed) {
92	          _fitLive();
93	        }
94	      });
95	    _play = AnimationController(vsync: this)
96	      ..addListener(_onPlayTick)
97	      ..addStatusListener((status) {
98	        // 只认 completed。dismissed 不是「播完」，而是 `forward(from: 0)`
99	        // 重置进度时同步触发的下界回调 —— 重播时若也在这里收尾，会把刚
100	        // 建立的播放态和 HUD 一起清掉，重播就只剩地图在动。
101	        if (status != AnimationStatus.completed) return;
102	        _liveHud.value = null;
103	        if (mounted && _playing) setState(() => _playing = false);
104	      });
105	  }
106	
107	  /// 回放每帧都会回调；底栏读数按 6 帧一次推（≈10 Hz）就够看了。
108	  ///
109	  /// 数字在 60 Hz 下大部分帧都是同一个字符串，重建 `Text` 只会白跑一遍排版。
110	  void _onPlayTick() {
111	    if (!_playing) return;
112	    if (++_hudTick % 6 != 0) return;
113	    _liveHud.value = _liveAt(_playCut);
114	  }
115	
116	  /// 游标 [cut] 处的瞬时读数。逐点数组与 `_pts` 等长（解析时对齐）。
117	  RideGlanceLive _liveAt(double cut) {
118	    final n = _pts.length;
119	    if (n == 0) {
120	      return (speedKmh: null, cadenceRpm: null, powerW: null, hrBpm: null);
121	    }
122	    final i = cut.round().clamp(0, n - 1);
123	    final sum = _sum;
124	    final speeds = sum?.pointSpeedsKmh ?? const <double>[];
125	    final cad = sum?.pointCadenceRpm ?? const <int?>[];
126	    final pw = sum?.pointPowerW ?? const <int?>[];
127	    final hr = sum?.pointHrBpm ?? const <int?>[];
128	    return (
129	      speedKmh: i < speeds.length ? speeds[i] : null,
130	      cadenceRpm: i < cad.length ? cad[i] : null,
131	      powerW: i < pw.length ? pw[i] : null,
132	      hrBpm: i < hr.length ? hr[i] : null,
133	    );
134	  }
