154	  Future<void> _loadPts() async {
155	    final rec = _rec;
156	    if (rec == null) return;
157	    final f = File(rec.localPath);
158	    if (!await f.exists()) return;
159	    final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
160	    final sum = GpxUtil.parse(xml);
161	    final speeds = sum.pointSpeedsKmh;
162	    // 回放时间轴：按「距离 / 速度」累加，快的地方画得快。
163	    final rideT = GpxUtil.cumulativeRideSeconds(sum.points, speeds);
164	    final total = rideT.isEmpty ? 0.0 : rideT.last;
165	    if (!mounted) return;
166	    _camCache.clear();
167	    _liveHud.value = null;
168	    setState(() {
169	      _sum = sum;
170	      _pts = sum.points;
171	      _disp = HelmOsmTiles.toDisplayAll(sum.points);
172	      _rideT = rideT;
173	      _rideTotal = total;
174	      _stops = RideTrackStyle.bandStops(
175	        speeds,
176	        fallbackKmh: sum.avgSpeedKmh ?? 18,
177	      );
178	      _kmMarks = GpxUtil.kmMarkers(sum.points);
179	    });
180	    _startPlayback();
181	  }
182	
183	  /// 进场自动回放一次。
184	  ///
185	  /// 把整段骑行时长等比压进 [_playMaxSec] 秒内播完：等比压缩保留了各段的快慢差别，
186	  /// 所以「以运动的速度绘制」这件事在压缩后依然成立。本来就比上限短的按实际时长播。
187	  void _startPlayback() {
188	    if (_disp.length < 2) return;
189	    final secs = _rideTotal > 0 ? _rideTotal : _playMaxSec;
190	    _play.duration = Duration(
191	      milliseconds: (secs.clamp(0.6, _playMaxSec) * 1000).round(),
192	    );
193	    _hudTick = 0;
194	    _playing = true;
195	    _liveHud.value = _liveAt(0);
196	    _play.forward(from: 0);
197	  }
198	
199	  /// 重播：底栏读数跟着游标从头走。
200	  ///
201	  /// 先 `forward` 再置播放态：`forward(from: 0)` 会把进度拉回下界，状态机
202	  /// 在这一步同步经过 dismissed，播放态放在它之后建立才不会被重置动作影响。
203	  void _restartPlayback() {
204	    if (_disp.length < 2) return;
205	    _hudTick = 0;
206	    _play.forward(from: 0);
207	    setState(() => _playing = true);
208	    _liveHud.value = _liveAt(0);
209	  }
210	
211	  /// 当前画到的小数下标（4.5 表示在第 4、5 点之间）。
212	  double get _playCut {
213	    if (_disp.length < 2) return 0;
214	    // 没有速度信息 → 没有时间轴，按点数均匀播。
215	    if (_rideT.length != _disp.length || _rideTotal <= 0) {
216	      return _play.value * (_disp.length - 1);
217	    }
218	    final sec = _play.value * _rideTotal;
219	    // 播完就整条。二进制查找找的是「第一个 >= sec 的下标」，如果尾部有一串
220	    // 零位移点（原地停留，累计时间相同）会停在那串的第一个上，线就画不到底、
221	    // 游标也不消失。
222	    if (sec >= _rideTotal) return _disp.length - 1;
223	    var lo = 0;
224	    var hi = _rideT.length - 1;
225	    while (lo < hi) {
226	      final mid = (lo + hi) >> 1;
227	      if (_rideT[mid] < sec) {
228	        lo = mid + 1;
229	      } else {
230	        hi = mid;
231	      }
232	    }
233	    final i = lo < 1 ? 1 : lo;
234	    final t0 = _rideT[i - 1];
235	    final t1 = _rideT[i];
236	    final f = t1 - t0 <= 0 ? 1.0 : ((sec - t0) / (t1 - t0)).clamp(0.0, 1.0);
237	    return (i - 1) + f;
238	  }
