240	  static const _mapPad = EdgeInsets.fromLTRB(40, 48, 40, 40);
241	  static const _mapPadPeek = EdgeInsets.fromLTRB(36, 80, 36, 100);
242	  static const _peekBody = 56.0;
243	
244	  void _fitLive() {
245	    if (!mounted || _disp.length < 2) return;
246	    final fit = _fitOf(
247	      _disp,
248	      padding: _sheet.value > 0.5 ? _mapPad : _mapPadPeek,
249	    );
250	    if (fit == null) return;
251	    try {
252	      _map.fitCamera(fit);
253	    } catch (_) {}
254	  }
255	
256	  void _onSheetDragUpdate(double dy, double bodyH) {
257	    final travel = bodyH * 0.5 - _peekBody;
258	    if (travel <= 8) return;
259	    if (_sheet.isAnimating) _sheet.stop();
260	    _sheet.value = (_sheet.value - dy / travel).clamp(0.0, 1.0);
261	  }
262	
263	  void _onSheetDragEnd(double velocity) {
264	    final next = velocity < -350
265	        ? 1.0
266	        : velocity > 350
267	            ? 0.0
268	            : _sheet.value >= 0.45
269	                ? 1.0
270	                : 0.0;
271	    _sheet.animateTo(next, curve: Curves.easeOutCubic);
272	  }
273	
274	  CameraFit? _fitOf(List<LatLng> pts, {EdgeInsets padding = _mapPad}) {
275	    if (pts.length < 2) return null;
276	    return CameraFit.bounds(
277	      bounds: LatLngBounds.fromPoints(pts),
278	      padding: padding,
279	      maxZoom: 16,
280	      minZoom: 3,
281	      forceIntegerZoomLevel: true,
282	    );
283	  }
284	
285	  /// 用控件真实尺寸算出第一帧相机，避免先对着起点再跳到整条轨迹。
286	  ///
287	  /// 结果按 [padding] 缓存：只在 FlutterMap 首次 build 时生效，之后控件重建、
288	  /// 抽屉拖动都不会用到它，重算等于每帧白跑一遍整条轨迹的投影。
289	  ({LatLng center, double zoom})? _cameraFor(
290	    List<LatLng> pts,
291	    Size size, {
292	    EdgeInsets padding = _mapPad,
293	  }) {
294	    final cached = _camCache[padding];
295	    if (cached != null) return cached;
296	    final fit = _fitOf(pts, padding: padding);
297	    if (fit == null || size.width < 8 || size.height < 8) return null;
298	    try {
299	      final fitted = fit.fit(
300	        MapCamera(
301	          crs: const Epsg3857(),
302	          center: pts.first,
303	          zoom: 10,
304	          rotation: 0,
305	          nonRotatedSize: size,
306	          minZoom: 3,
307	          maxZoom: 18,
308	        ),
309	      );
310	      final cam = (center: fitted.center, zoom: fitted.zoom);
311	      _camCache[padding] = cam;
312	      return cam;
313	    } catch (_) {
314	      return null;
315	    }
316	  }
317	
318	  void _fitTrack(MapController map) {
319	    final fit = _fitOf(_disp, padding: _mapPadPeek);
320	    if (fit == null) return;
321	    try {
322	      map.fitCamera(fit);
323	    } catch (_) {}
324	  }
