376	  Future<void> _shareImage() async {
377	    final rec = _rec;
378	    if (rec == null || _sharing) return;
379	    setState(() => _sharing = true);
380	    try {
381	      await WidgetsBinding.instance.endOfFrame;
382	      if (!mounted) return;
383	      if (_pts.length >= 2) {
384	        _fitTrack(_shareMap);
385	        await Future<void>.delayed(const Duration(milliseconds: 700));
386	      }
387	      if (!mounted) return;
388	      final boundary =
389	          _shotKey.currentContext?.findRenderObject() as RenderRepaintBoundary?;
390	      if (boundary == null) {
391	        throw StateError('map not ready');
392	      }
393	      final dpr = MediaQuery.devicePixelRatioOf(context).clamp(2.0, 3.0);
394	      final image = await boundary.toImage(pixelRatio: dpr);
395	      final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
396	      if (bytes == null) {
397	        throw StateError('empty png');
398	      }
399	      final dir = await getTemporaryDirectory();
400	      final stem = rec.fileName.toLowerCase().endsWith('.gpx')
401	          ? rec.fileName.substring(0, rec.fileName.length - 4)
402	          : rec.fileName;
403	      final file = File(p.join(dir.path, 'helm_$stem.png'));
404	      await file.writeAsBytes(bytes.buffer.asUint8List(), flush: true);
405	      final caption = RidePoster.shareCaption(rec, _sum);
406	      await SharePlus.instance.share(
407	        ShareParams(
408	          files: [
409	            XFile(file.path, mimeType: 'image/png', name: '${rec.title}.png'),
410	          ],
411	          text: caption,
412	        ),
413	      );
414	    } catch (e, st) {
415	      if (!mounted) return;
416	      AppTheme.fail(LocaleKeys.rideShareImage.tr, 'RideShare', e, st);
417	    } finally {
418	      if (mounted) setState(() => _sharing = false);
419	    }
420	  }
