524	                                        child: RideGlanceOverlay(
525	                                          rec: rec,
526	                                          summary: _sum,
527	                                          live: _liveHud,
528	                                        ),
529	                                      ),
530	                                    ),
531	                                ],
532	                              ),
533	                            ),
534	                            SizedBox(
535	                              height: sheetH.clamp(_peekBody, h * 0.5),
536	                              child: _RideDataSheet(
537	                                rec: rec,
538	                                summary: _sum,
539	                                expanded: t > 0.04,
540	                                sharing: _sharing,
541	                                playing: _playing,
542	                                onReplay: _restartPlayback,
543	                                onShare: _shareImage,
544	                                onDelete: _delete,
545	                                onDragUpdate: (dy) =>
546	                                    _onSheetDragUpdate(dy, h),
547	                                onDragEnd: _onSheetDragEnd,
548	                                onHeaderTap: () {
549	                                  if (_sheet.value < 0.5) {
550	                                    _sheet.animateTo(
551	                                      1,
552	                                      curve: Curves.easeOutCubic,
553	                                    );
554	                                  } else {
555	                                    _sheet.animateTo(
556	                                      0,
557	                                      curve: Curves.easeOutCubic,
558	                                    );
559	                                  }
560	                                },
561	                              ),
562	                            ),
563	                          ],
564	                        ),
