594	  /// [playable] 为 true 时地图跟着回放进度重建（只有详情页的主地图要）。
595	  Widget _mapView(
596	    MapController controller, {
597	    EdgeInsets fitPad = _mapPad,
598	    bool playable = false,
599	  }) {
600	    if (_disp.isEmpty) {
601	      return const ColoredBox(
602	        color: Color(0xFFEDE8DF),
603	        child: Center(
604	          child: Icon(Icons.map_outlined, color: AppTheme.muted, size: 48),
605	        ),
606	      );
607	    }
608	    Widget build({required double? cut}) => LayoutBuilder(
609	      builder: (context, box) {
610	        final mapSize = Size(box.maxWidth, box.maxHeight);
611	        if (mapSize.width < 8 || mapSize.height < 8) {
612	          return const ColoredBox(color: Color(0xFFEDE8DF));
613	        }
614	        final cam = _cameraFor(_disp, mapSize, padding: fitPad);
615	        // 单独一层：抽屉拖动 / 底栏刷新不会把地图的栅格一起标脏。
616	        return RepaintBoundary(
617	          child: FlutterMap(
618	            mapController: controller,
619	            options: MapOptions(
620	              initialCenter: cam?.center ?? _disp.first,
621	              initialZoom: cam?.zoom ?? 14,
622	              minZoom: 3,
623	              maxZoom: 18,
624	              interactionOptions: const InteractionOptions(
625	                flags: InteractiveFlag.all & ~InteractiveFlag.rotate,
626	              ),
627	              backgroundColor: const Color(0xFFEDE8DF),
628	            ),
629	            children: [
630	              HelmOsmTiles.layer(
631	                tileDisplay: const TileDisplay.instantaneous(),
632	              ),
633	              ...rideTrackLayers(
634	                display: _disp,
635	                summary: _sum,
636	                wgs: _pts,
637	                stops: _stops,
638	                cut: cut,
639	                kmMarks: _kmMarks,
640	              ),
641	            ],
642	          ),
643	        );
644	      },
645	    );
646	
647	    // 分享封面用完整轨迹，不参与回放。
648	    if (!playable) return build(cut: null);
649	    // 只让地图这一层跟着回放重建：整页 60 fps 重建会把面板和榜单一起带上。
650	    return ListenableBuilder(
651	      listenable: _play,
652	      builder: (context, _) => build(cut: _playCut),
653	    );
654	  }
