852	/// 抽屉里的卡片错峰入场：展开时逐张上浮淡入。
853	///
854	/// 用 `Interval` 在一条 Tween 里做出延迟，不额外起 Timer / Controller；
855	/// 抽屉收起时 ListView 整体销毁，再展开自然重播一次。
856	class _Reveal extends StatelessWidget {
857	  const _Reveal({required this.index, required this.child});
858	
859	  final int index;
860	  final Widget child;
861	
862	  @override
863	  Widget build(BuildContext context) {
864	    return TweenAnimationBuilder<double>(
865	      tween: Tween<double>(begin: 0, end: 1),
866	      duration: const Duration(milliseconds: 560),
867	      curve: Interval(
868	        (index * 0.08).clamp(0.0, 0.5),
869	        1,
870	        curve: Curves.easeOutCubic,
871	      ),
872	      builder: (context, t, child) => Opacity(
873	        opacity: t,
874	        child: Transform.translate(offset: Offset(0, 12 * (1 - t)), child: child),
875	      ),
876	      child: child,
877	    );
878	  }
879	}
